37	export const deriveMediaFilename = ({
38	  src,
39	  index,
40	  blob,
41	}: MediaFilenameParams): string => {
42	  // Default base name
43	  let baseName = `media-${index + 1}`;
44	
45	  // Try to reuse the last path segment for non data URLs.
46	  if (!src.startsWith('data:')) {
47	    try {
48	      const url = new URL(src, window.location.origin);
49	      const lastSegment = url.pathname.split('/').pop();
50	      if (lastSegment) {
51	        baseName = `${index + 1}-${lastSegment}`;
52	      }
53	    } catch {
54	      // Ignore invalid URLs, keep default baseName.
55	    }
56	  }
57	
58	  let filename = baseName;
59	
60	  // Ensure the filename has an extension consistent with the blob MIME type.
61	  const mimeType = blob.type;
62	  if (mimeType && !baseName.includes('.')) {
63	    const slashIndex = mimeType.indexOf('/');
64	    const rawSubtype =
65	      slashIndex !== -1 && slashIndex < mimeType.length - 1
66	        ? mimeType.slice(slashIndex + 1)
67	        : '';
68	
69	    let extension = '';
70	    const subtype = rawSubtype.toLowerCase();
71	
72	    if (subtype.includes('svg')) {
73	      extension = 'svg';
74	    } else if (subtype.includes('jpeg') || subtype.includes('pjpeg')) {
75	      extension = 'jpg';
76	    } else if (subtype.includes('png')) {
77	      extension = 'png';
78	    } else if (subtype.includes('gif')) {
79	      extension = 'gif';
80	    } else if (subtype.includes('webp')) {
81	      extension = 'webp';
82	    } else if (subtype.includes('pdf')) {
83	      extension = 'pdf';
84	    } else if (subtype) {
85	      extension = subtype.split('+')[0];
86	    }
87	
88	    if (extension) {
89	      filename = `${baseName}.${extension}`;
90	    }
91	  }
92	
93	  return filename;
94	};
